import axios from 'axios';
import { GroupedHistoryItem, QuestionResponse, UserProgress } from '../types';

const API_BASE_URL = '/api/questions';
const API_TIMEOUT = 30000;

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: API_TIMEOUT
});

export function getErrorMessage(error: unknown): string {
  if (axios.isAxiosError(error)) {
    const serverMessage = error.response?.data?.error;
    if (typeof serverMessage === 'string' && serverMessage.trim()) {
      return serverMessage;
    }
    if (error.code === 'ECONNABORTED') {
      return '请求超时，请稍后重试。';
    }
    if (!error.response) {
      return '网络连接失败，请确认后端服务是否正常运行。';
    }
    return '服务暂时不可用，请稍后重试。';
  }
  if (error instanceof Error && error.message) {
    return error.message;
  }
  return '发生未知错误，请稍后重试。';
}

export const askQuestion = async (question: string, description?: string, userId: string = 'default_user'): Promise<QuestionResponse> => {
  const response = await api.post('/ask', {
    question,
    description,
    userId
  });
  return response.data;
};

export interface CategoryInfo {
  id: string;
  name: string;
  icon: string;
  count: number;
}

export const getCategories = async (): Promise<CategoryInfo[]> => {
  const response = await api.get('/categories');
  return response.data;
};

export const getUserProgress = async (userId: string = 'default_user'): Promise<UserProgress> => {
  const response = await api.get('/progress', {
    params: { userId }
  });
  return response.data;
};

export const getUserProgressText = async (userId: string = 'default_user'): Promise<{ progress: string }> => {
  const response = await api.get('/progress/text', {
    params: { userId }
  });
  return response.data;
};

export const clearUserHistory = async (userId: string = 'default_user'): Promise<{ message: string }> => {
  const response = await api.post('/history/clear', { userId });
  return response.data;
};

export interface UserServiceMetric {
  userId: string;
  totalRequests: number;
  slowRequests: number;
  failedRequests: number;
  avgResponseTimeMs: number;
  lastResponseTimeMs: number;
  lastRiskLevel: string;
  lastSeenAt: string;
}

export interface UserServiceMetricsResponse {
  summary: {
    totalUsersTracked: number;
    totalRequests: number;
    slowRequests: number;
    failedRequests: number;
  };
  thresholdMs: number;
  users: UserServiceMetric[];
}

export const getUserServiceMetrics = async (): Promise<UserServiceMetricsResponse> => {
  const response = await api.get('/service-metrics');
  return response.data;
};

export interface AlertItem {
  level: 'high' | 'medium';
  message: string;
  userId: string;
  time: string;
}

export const getAlerts = async (): Promise<{ count: number; alerts: AlertItem[] }> => {
  const response = await api.get('/alerts');
  return response.data;
};

export const getGroupedHistory = async (userId: string): Promise<{ userId: string; groups: Record<string, GroupedHistoryItem[]> }> => {
  const response = await api.get('/history/grouped', { params: { userId } });
  return response.data;
};
